import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import LandingPage from './components/LandingPage';
import Visualization from './components/Visualization';
import Prediction from './components/Prediction';
import Login from './components/Login';
import Signup from './components/Signup';
import { AppProvider } from './components/AppContext'; // ✅ Import your context provider
import './App.css';

function App() {
  const [token, setToken] = useState(() => localStorage.getItem('token'));

  useEffect(() => {
    if (token) localStorage.setItem('token', token);
    else localStorage.removeItem('token');
  }, [token]);

  const PrivateRoute = ({ children }) => {
    return token ? children : <Navigate to="/login" />;
  };

  const PublicRoute = ({ children }) => {
    return !token ? children : <Navigate to="/landing" />;
  };

  return (
    <AppProvider> {/* ✅ Wrap everything in AppProvider */}
      <Router>
        <div className="app-container">
          <Routes>
            <Route path="/" element={token ? <Navigate to="/landing" /> : <Navigate to="/login" />} />

            {/* Public Pages */}
            <Route
              path="/login"
              element={
                <PublicRoute>
                  <Login onLogin={setToken} />
                </PublicRoute>
              }
            />
            <Route
              path="/signup"
              element={
                <PublicRoute>
                  <Signup />
                </PublicRoute>
              }
            />

            {/* Private Pages */}
            <Route
              path="/landing"
              element={
                <PrivateRoute>
                  <LandingPage onLogout={() => setToken(null)} />
                </PrivateRoute>
              }
            />
            <Route
              path="/visualization"
              element={
                <PrivateRoute>
                  <Visualization />
                </PrivateRoute>
              }
            />
            <Route
              path="/prediction"
              element={
                <PrivateRoute>
                  <Prediction token={token} />
                </PrivateRoute>
              }
            />

            {/* Redirect all other routes */}
            <Route path="*" element={<Navigate to="/" />} />
          </Routes>
        </div>
      </Router>
    </AppProvider>
  );
}

export default App;
